insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo de habilitação e de reabilitação é um direito da pessoa com deficiência. Tem por objetivo o desenvolvimento de potencialidades, talentos, habilidades e aptidões físicas, cognitivas, sensoriais, psicossociais, atitudinais, profissionais e artísticas que contribuam para a conquista da autonomia e da participação social em igualdade de condições.', '["Habilitação e reabilitação como direito.","Desenvolvimento de potencialidades e autonomia."]'::jsonb, '["Habilitação e reabilitação são DIREITOS."]'::jsonb, 'O programa de reabilitação ajuda a pessoa a recuperar autonomia.', '["Assertiva que trata a reabilitação como mera faculdade do Estado erra: é direito da pessoa."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-14' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e9a79131e92c351e2b94ac3a73e559701da799a8633807946c13a76d80f7d354'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo de habilitação e reabilitação baseia-se em avaliação multidisciplinar das necessidades, habilidades e potencialidades de cada pessoa, observadas as diretrizes de diagnóstico e intervenção precoces; medidas para compensar perda ou limitação funcional; atuação permanente, integrada e articulada de políticas públicas; rede de serviços articulados, com atuação intersetorial; e prestação de serviços próximo ao domicílio, inclusive na zona rural, respeitadas as Redes de Atenção à Saúde e as normas do SUS.', '["Avaliação multidisciplinar.","Diagnóstico e intervenção precoces.","Rede intersetorial.","Serviços perto do domicílio, inclusive na zona rural."]'::jsonb, '["Serviços próximos ao domicílio, inclusive no meio rural."]'::jsonb, 'A criança tem diagnóstico e intervenção precoces perto de casa.', '["Assertiva que restringe os serviços de reabilitação às capitais erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-15' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e43e64b12d2e21113e30108cbc0651305e5e7142d516a5073304998d88a34b97'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos programas e serviços de habilitação e de reabilitação, são garantidos organização, serviços, métodos, técnicas e recursos para atender às características de cada pessoa; acessibilidade em todos os ambientes e serviços; tecnologia assistiva, tecnologia de reabilitação, materiais e equipamentos adequados e apoio técnico profissional; e capacitação continuada de todos os profissionais.', '["Atendimento individualizado.","Acessibilidade.","Tecnologia assistiva e apoio técnico.","Capacitação continuada dos profissionais."]'::jsonb, '["Quatro garantias."]'::jsonb, 'O centro de reabilitação adapta os métodos a cada paciente.', '["Assertiva que dispensa a capacitação dos profissionais erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-16' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8f0cde35a34b00d7fbb0ed8b3df048c9ef51a8e0a5f7bf33f714c80a77cc7d7c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os serviços do SUS e do Suas deverão promover ações articuladas para garantir à pessoa com deficiência e sua família a aquisição de informações, orientações e formas de acesso às políticas públicas, com a finalidade de propiciar sua plena participação social. Podem fornecer informações em saúde, educação, cultura, esporte, lazer, transporte, previdência, assistência, habitação, trabalho, empreendedorismo, crédito e defesa de direitos.', '["Ações articuladas do SUS e do Suas.","Informações e orientações sobre políticas públicas."]'::jsonb, '["Articulação entre saúde e assistência social."]'::jsonb, 'O serviço do Suas orienta a família sobre os benefícios disponíveis.', '["Assertiva que restringe a orientação a temas de saúde erra."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-17' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'de1d65e7a28dbeb3cde267fafa5408eb978e9d97b87076b74d6564f2440341ee'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurada atenção integral à saúde da pessoa com deficiência em todos os níveis de complexidade, por intermédio do SUS, com acesso universal e igualitário. Assegura-se participação na elaboração das políticas de saúde, atendimento segundo normas éticas e técnicas, capacitação inicial e continuada dos profissionais e ações de saúde pública com diagnóstico e intervenção precoces por equipe multidisciplinar, serviços de habilitação e reabilitação, atendimento domiciliar multidisciplinar, tratamento ambulatorial e internação, campanhas de vacinação e atendimento psicológico, inclusive para familiares e atendentes pessoais.', '["Atenção integral pelo SUS.","Participação na elaboração das políticas.","Diagnóstico precoce, reabilitação e atendimento domiciliar.","Apoio psicológico a familiares e atendentes."]'::jsonb, '["Atendimento psicológico alcança familiares e atendentes."]'::jsonb, 'O SUS oferece atendimento domiciliar multidisciplinar à pessoa com deficiência.', '["Assertiva que exclui o apoio psicológico a familiares erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-18' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a4f8db7f47d2bd068347c2760eca887f761f40868ee03607f72c1c4e04048b2b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao SUS desenvolver ações destinadas à prevenção de deficiências por causas evitáveis, inclusive por meio de acompanhamento da gravidez, do parto e do puerpério com parto humanizado e seguro; promoção de práticas alimentares adequadas; aprimoramento dos programas de imunização e de triagem neonatal; identificação e controle da gestante de alto risco; e aprimoramento do atendimento neonatal para prevenir danos cerebrais e sequelas neurológicas em recém-nascidos, inclusive por telessaúde.', '["Prevenção de deficiências evitáveis.","Acompanhamento da gravidez, parto e puerpério.","Imunização e triagem neonatal.","Atendimento neonatal."]'::jsonb, '["ATUALIZAÇÃO: o inciso V (atendimento neonatal e telessaúde) foi incluído por lei posterior."]'::jsonb, 'A triagem neonatal identifica doenças que podem causar deficiência.', '["Assertiva que exclui a triagem neonatal das ações de prevenção erra."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-19' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3e768cd4c88128a40327d3a88c540e194ad846260868780e7bf9440dae336aeb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
