insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As operadoras de planos e seguros privados de saúde são obrigadas a garantir à pessoa com deficiência, no mínimo, todos os serviços e produtos ofertados aos demais clientes.', '["Planos de saúde: pelo menos os mesmos serviços e produtos aos demais clientes."]'::jsonb, '["Cobertura NO MÍNIMO igual à dos demais clientes."]'::jsonb, 'O plano não pode oferecer cobertura reduzida à pessoa com deficiência.', '["Assertiva que permite ao plano limitar a cobertura da pessoa com deficiência erra."]'::jsonb, '[]'::jsonb, '["Art. 23"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-20' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '03d0b3a0226943715da5a867321933f5e5cc5393b22e81c60c1598cb05ec017e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando esgotados os meios de atenção à saúde da pessoa com deficiência no local de residência, será prestado atendimento fora de domicílio, para fins de diagnóstico e tratamento, garantidos o transporte e a acomodação da pessoa com deficiência e de seu acompanhante.', '["Atendimento fora de domicílio.","Transporte e acomodação da pessoa e do acompanhante."]'::jsonb, '["Custeio do transporte e da hospedagem do acompanhante."]'::jsonb, 'Sem especialista na cidade, o SUS custeia o tratamento e a hospedagem em outra cidade.', '["Assertiva que exclui o acompanhante do transporte e da acomodação erra."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-21' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f948be3a248653160f96d431f2a7c3a72c68c7c504b2ea0ea0ec1928bc752f4b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
