insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa com deficiência tem direito à cultura, ao esporte, ao turismo e ao lazer em igualdade de oportunidades, sendo-lhe garantido o acesso a bens culturais em formato acessível; a programas de televisão, cinema, teatro e atividades culturais e desportivas em formato acessível; e a monumentos e espaços culturais. É vedada a recusa de oferta de obra intelectual em formato acessível, sob qualquer argumento, inclusive a proteção da propriedade intelectual. O poder público deve eliminar barreiras ao patrimônio cultural, observadas as normas de proteção, e incentivará museus e exposições a empregar comunicação aumentativa e alternativa.', '["Acesso à cultura, esporte, turismo e lazer.","Formato acessível.","Vedada a recusa de obra em formato acessível, mesmo por direito autoral."]'::jsonb, '["Direito autoral NÃO justifica a recusa de formato acessível."]'::jsonb, 'A editora não pode recusar a versão acessível de um livro alegando direito autoral.', '["Assertiva que admite a recusa de formato acessível com base na propriedade intelectual erra."]'::jsonb, '[]'::jsonb, '["Art. 43"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-42' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '62067f2b05d563ec66d5edab00298aaae8ecf567bd63f8fe936c9c2bc131ec2d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve promover a participação da pessoa com deficiência em atividades artísticas, intelectuais, culturais, esportivas e recreativas, com vistas ao seu protagonismo, incentivando a provisão de instrução, treinamento e recursos adequados; assegurando acessibilidade nos locais de eventos e nos serviços; e assegurando a participação em jogos e atividades recreativas, esportivas, de lazer, culturais e artísticas, inclusive no sistema escolar.', '["Participação em atividades artísticas, esportivas e culturais.","Acessibilidade nos locais de eventos.","Participação no sistema escolar."]'::jsonb, '["Foco no PROTAGONISMO."]'::jsonb, 'A escola inclui o aluno com deficiência nas atividades esportivas.', '["Assertiva que restringe o direito ao esporte ao nível competitivo erra."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-43' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '961806f39432194ad14388d0a1fe3b6f4e4da2afc82ccf7f9bf72a6d462dd620'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos teatros, cinemas, auditórios, estádios, ginásios e locais de espetáculos e conferências serão reservados espaços livres e assentos para a pessoa com deficiência, de acordo com a capacidade de lotação, conforme regulamento. Devem ser distribuídos em locais diversos, de boa visibilidade, em todos os setores, próximos aos corredores e sinalizados, evitando áreas segregadas. Se não houver comprovada procura, podem, excepcionalmente, ser ocupados por pessoas sem deficiência. Devem acomodar, no mínimo, 1 acompanhante. Deve haver rotas de fuga e saídas de emergência acessíveis.', '["Espaços e assentos reservados.","Distribuídos em todos os setores, sem segregação.","Pelo menos 1 acompanhante.","Rotas de fuga acessíveis."]'::jsonb, '["Vedadas áreas SEGREGADAS.","Mínimo de 1 acompanhante."]'::jsonb, 'O estádio distribui os assentos acessíveis por todos os setores.', '["Assertiva que permite concentrar os assentos acessíveis em um só setor erra: evitam-se áreas segregadas."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-44' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e3c9b024a3f25daea70846c00ff62998a8a3dc1d0812fd28acc2fd0e47b44e63'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os hotéis, pousadas e similares devem ser construídos observando os princípios do desenho universal, além de adotar todos os meios de acessibilidade. Os estabelecimentos já existentes deverão disponibilizar, pelo menos, 10% de seus dormitórios acessíveis, garantida no mínimo 1 unidade, localizados em rotas acessíveis. Os que, por impossibilidade técnica decorrente de riscos estruturais, não possam cumprir o percentual ficam dispensados mediante laudo técnico estrutural, renovado a cada 5 anos.', '["Hotéis novos: desenho universal.","Existentes: pelo menos 10% de dormitórios acessíveis.","Dispensa por laudo estrutural renovado a cada 5 anos."]'::jsonb, '["Mínimo de 10% dos dormitórios, e ao menos 1.","Laudo renovado a cada 5 anos."]'::jsonb, 'O hotel antigo tem 10% de quartos acessíveis, ou laudo que o dispense.', '["Assertiva que fixa em 2% os dormitórios acessíveis erra: são 10%."]'::jsonb, '[]'::jsonb, '["Art. 125"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-45' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3d6cfc3d507d74946fdd33bd3939249f2ecf95d88291c076189bdce8ccb4950b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
