on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O direito ao transporte e à mobilidade da pessoa com deficiência ou com mobilidade reduzida será assegurado em igualdade de oportunidades, por meio da identificação e eliminação de todos os obstáculos e barreiras. Consideram-se integrantes dos serviços de transporte coletivo terrestre, aquaviário e aéreo os veículos, terminais, estações, pontos de parada, sistema viário e a prestação do serviço. Sujeitam-se à Lei a outorga, concessão, permissão, autorização, renovação ou habilitação de linhas e serviços. Para o símbolo internacional de acesso nos veículos, as empresas dependem de certificação de acessibilidade do gestor público.', '["Eliminação de barreiras no transporte.","Veículos, terminais, estações e sistema viário.","Concessões sujeitas à acessibilidade.","Certificação para o símbolo de acesso."]'::jsonb, '["Símbolo de acesso depende de CERTIFICAÇÃO do gestor público."]'::jsonb, 'A concessão de linhas de ônibus exige o cumprimento das regras de acessibilidade.', '["Assertiva que permite colocar o símbolo de acesso sem certificação erra."]'::jsonb, '[]'::jsonb, '["Art. 48"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-46' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8a92062c49d9842c8046a6f1e18e2a878c85470a1b0d8735180c7f4de271a53b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em todas as áreas de estacionamento aberto ao público, de uso público ou privado de uso coletivo e em vias públicas, devem ser reservadas vagas próximas aos acessos de circulação de pedestres, sinalizadas, para veículos que transportem pessoa com deficiência com comprometimento de mobilidade. As vagas equivalem a 2% do total, garantida no mínimo 1. Os veículos devem exibir a credencial de beneficiário, fornecida pelos órgãos de trânsito. A utilização indevida sujeita o infrator às sanções do Código de Trânsito. A credencial é vinculada à pessoa e válida em todo o território nacional.', '["Vagas reservadas: 2% do total, no mínimo 1.","Credencial de beneficiário.","Uso indevido: sanções do CTB.","Credencial vinculada à pessoa e nacional."]'::jsonb, '["Vagas de PCD: 2%; idosos: 5% (Estatuto da Pessoa Idosa).","A credencial é da PESSOA, e vale em todo o território nacional."]'::jsonb, 'A pessoa com deficiência usa a credencial em qualquer cidade do País.', '["Assertiva que fixa em 5% as vagas reservadas a pessoas com deficiência erra: são 2%."]'::jsonb, '[]'::jsonb, '["Código de Trânsito Brasileiro"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-47' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'edc2126347f20c4591cf5d146d6648a08feacb46f0395f0cb54d4c37511da94f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos de transporte coletivo terrestre, aquaviário e aéreo, as instalações, estações, portos e terminais em operação devem ser acessíveis, de forma a garantir o seu uso por todas as pessoas. Devem dispor de sistema de comunicação acessível sobre os pontos do itinerário. São asseguradas prioridade e segurança nos procedimentos de embarque e desembarque. Para o símbolo internacional de acesso, as empresas dependem da certificação do gestor público.', '["Veículos, terminais e portos acessíveis.","Comunicação acessível sobre o itinerário.","Prioridade e segurança no embarque e desembarque."]'::jsonb, '["Certificação de acessibilidade para o símbolo."]'::jsonb, 'O ônibus anuncia as paradas de forma acessível a pessoas com deficiência visual.', '["Assertiva que restringe a acessibilidade aos veículos novos erra: abrange os em operação."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-48' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9f9156d92b924d34f05e5e2a6f77a0c608e650c747e4b2b8b8bf83eeba943f8a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As empresas de transporte de fretamento e de turismo, na renovação de suas frotas, são obrigadas ao cumprimento do disposto nos arts. 46 e 48.', '["Fretamento e turismo cumprem a acessibilidade na renovação da frota."]'::jsonb, '["Obrigação na RENOVAÇÃO da frota."]'::jsonb, 'A empresa de turismo adquire ônibus acessíveis ao renovar a frota.', '["Assertiva que exige substituição imediata de toda a frota erra: a obrigação ocorre na renovação."]'::jsonb, '[]'::jsonb, '["Art. 125"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-49' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e7e15b9cae84bb9b76226474770b5efd2626b8c077d7a05aafa1459173085b67'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público incentivará a fabricação de veículos acessíveis e a sua utilização como táxis e vans, de forma a garantir o seu uso por todas as pessoas.', '["Incentivo à fabricação de veículos acessíveis."]'::jsonb, '["Incentivo, e não obrigação direta."]'::jsonb, 'O governo oferece incentivos para táxis acessíveis.', '["Assertiva que proíbe incentivos à fabricação de veículos acessíveis erra."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-50' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '39934ce4547b06e5c7eaf0913c882226e280b49a4f1948419f84876ee42e0a81'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As frotas de empresas de táxi devem reservar 10% de seus veículos acessíveis à pessoa com deficiência. É proibida a cobrança diferenciada de tarifas ou valores adicionais pelo serviço de táxi prestado à pessoa com deficiência. O poder público é autorizado a instituir incentivos fiscais para possibilitar a acessibilidade dos veículos.', '["10% da frota de táxis acessível.","Vedada a cobrança adicional.","Incentivos fiscais autorizados."]'::jsonb, '["Reserva de 10% da frota."]'::jsonb, 'A cooperativa de táxi mantém 10% de veículos acessíveis.', '["Assertiva que permite cobrar valor adicional da pessoa com deficiência erra: é proibido."]'::jsonb, '[]'::jsonb, '["Art. 119"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-51' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '04ed77fec00f5ccde937893c04954d04a0e83f2ae245c42c5d3409a0b8c248a4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As locadoras de veículos são obrigadas a oferecer 1 veículo adaptado para uso de pessoa com deficiência, a cada conjunto de 20 veículos de sua frota. O veículo adaptado deverá ter, no mínimo, câmbio automático, direção hidráulica, vidros elétricos e comandos manuais de freio e de embreagem.', '["1 veículo adaptado a cada 20 da frota.","Câmbio automático, direção hidráulica, vidros elétricos e comandos manuais."]'::jsonb, '["Proporção de 1 para 20."]'::jsonb, 'A locadora com 40 carros mantém 2 veículos adaptados.', '["Assertiva que fixa 1 veículo adaptado para cada 100 da frota erra: é 1 para cada 20."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-52' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4328dfa50ba585dc1551cf4aab87282ce74d900690b1ce8e5ab241d95893027f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A acessibilidade é direito que garante à pessoa com deficiência ou com mobilidade reduzida viver de forma independente e exercer seus direitos de cidadania e de participação social.', '["Acessibilidade como direito instrumental da vida independente."]'::jsonb, '["Direito que viabiliza outros direitos."]'::jsonb, 'A rampa permite que a pessoa exerça sua cidadania.', '["Assertiva que trata a acessibilidade como mera recomendação erra: é direito."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-53' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1f3e4afce5fea5cb97c5c10a8c4b1263d7cb7279088ab5558b4090c93a532a07'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sujeitam-se ao cumprimento da Lei e das normas de acessibilidade, sempre que houver interação com a matéria: a aprovação de projeto arquitetônico e urbanístico ou de comunicação e informação, a fabricação de veículos de transporte coletivo, a prestação do serviço e a execução de qualquer obra de destinação pública ou coletiva; a outorga ou renovação de concessão, permissão, autorização ou habilitação; a aprovação de financiamento de projeto com recursos públicos, por renúncia ou incentivo fiscal, contrato ou convênio; e a concessão de aval da União para empréstimo e financiamento internacionais.', '["Aprovação de projetos e obras de destinação coletiva.","Concessões e permissões.","Financiamento com recursos públicos.","Aval da União para empréstimos internacionais."]'::jsonb, '["Acessibilidade é condição para concessões, financiamentos e avais."]'::jsonb, 'O financiamento público de uma obra exige o cumprimento das regras de acessibilidade.', '["Assertiva que dispensa a acessibilidade nas obras financiadas com recursos públicos erra."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-54' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '03bf9f0fcee93ebce949f706a891babc2a2614366deacfeeffffb8ba3abdb2d1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A concepção e a implantação de projetos que tratem do meio físico, de transporte, de informação e comunicação e de outros serviços abertos ao público devem atender aos princípios do desenho universal, tendo como referência as normas de acessibilidade. O desenho universal será sempre a regra geral. Se comprovadamente não puder ser empreendido, deve ser adotada adaptação razoável. O poder público promoverá a inclusão do tema nas diretrizes curriculares e nos programas de pesquisa e considerará o desenho universal desde a concepção das políticas públicas.', '["Desenho universal como regra geral.","Adaptação razoável quando inviável.","Inclusão do tema nos currículos e pesquisas."]'::jsonb, '["Desenho universal é a REGRA; adaptação razoável é a exceção."]'::jsonb, 'A prefeitura projeta uma praça já com acessibilidade, em vez de adaptá-la depois.', '["Assertiva que torna a adaptação razoável a regra geral erra: a regra é o desenho universal."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-55' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd7a7cb09e4673746f9704781e512e8a729b6c8273e1e3da5fe7a4a32659366e6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A construção, reforma, ampliação ou mudança de uso de edificações abertas ao público, de uso público ou privadas de uso coletivo deverão ser executadas de modo a serem acessíveis. As entidades de fiscalização profissional devem exigir, ao anotarem a responsabilidade técnica, a declaração de atendimento às regras de acessibilidade. Para aprovação, licenciamento ou certificado de conclusão de obra, deve ser atestado o atendimento às regras. O poder público, após certificar a acessibilidade, determinará a colocação do símbolo internacional de acesso.', '["Edificações coletivas devem ser acessíveis.","Responsabilidade técnica com declaração de acessibilidade.","Licenciamento e habite-se condicionados.","Símbolo de acesso após certificação."]'::jsonb, '["O profissional declara a observância das regras de acessibilidade."]'::jsonb, 'O arquiteto declara o atendimento à acessibilidade ao registrar a responsabilidade técnica.', '["Assertiva que dispensa o atestado de acessibilidade para o certificado de conclusão de obra erra."]'::jsonb, '[]'::jsonb, '["Art. 57"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-56' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'dff5e5810be770b04767b9ec93335f3cfd08c48a6e0a8ab9628cc6a1729e8a1f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As edificações públicas e privadas de uso coletivo já existentes devem garantir acessibilidade à pessoa com deficiência em todas as suas dependências e serviços, tendo como referência as normas de acessibilidade vigentes.', '["Edificações existentes também devem ser acessíveis."]'::jsonb, '["Alcança as edificações JÁ EXISTENTES."]'::jsonb, 'O prédio antigo de uso público deve ser adaptado.', '["Assertiva que isenta as edificações existentes erra."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-57' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4f60b7204565ea45ac9071690847b57814df0d2876c6f2ed270654be88c41a2b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
