insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer intervenção nas vias e espaços públicos, o poder público e as empresas concessionárias responsáveis pelas obras e serviços devem garantir, de forma segura, a fluidez do trânsito e a livre circulação e acessibilidade das pessoas, durante e após sua execução.', '["Obras em vias públicas garantem circulação e acessibilidade, durante e depois."]'::jsonb, '["Vale DURANTE e APÓS a obra."]'::jsonb, 'A obra na calçada mantém uma passagem segura para cadeirantes.', '["Assertiva que limita o dever ao período posterior à obra erra."]'::jsonb, '[]'::jsonb, '["Art. 55"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-59' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4908536a4249488141b876dda42feb47dd3e739d0383de2c1969837aac1eeb81'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
