insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurado à pessoa com deficiência, mediante solicitação, o recebimento de contas, boletos, recibos, extratos e cobranças de tributos em formato acessível.', '["Contas, boletos e extratos em formato acessível, mediante solicitação."]'::jsonb, '["Depende de SOLICITAÇÃO."]'::jsonb, 'A pessoa cega pede o extrato do banco em Braille.', '["Assertiva que torna a emissão acessível automática, sem solicitação, erra."]'::jsonb, '[]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-62' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8fea9fe6a0d261652e3075efb436e24e9b307ab80b6f378f18822c700c55855a'
