insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigatória a acessibilidade nos sítios da internet mantidos por empresas com sede ou representação comercial no País ou por órgãos de governo, para uso da pessoa com deficiência, conforme as melhores práticas e diretrizes internacionais. Os sítios devem conter símbolo de acessibilidade em destaque. Telecentros comunitários que recebam recursos públicos federais e lan houses devem possuir equipamentos e instalações acessíveis, garantindo, no mínimo, 10% de seus computadores com recursos de acessibilidade para pessoa com deficiência visual, com pelo menos 1 equipamento.', '["Acessibilidade obrigatória nos sítios de empresas e do governo.","Símbolo de acessibilidade em destaque.","Telecentros e lan houses: no mínimo 10% dos computadores acessíveis."]'::jsonb, '["Mínimo de 10% dos computadores, e pelo menos 1."]'::jsonb, 'A loja virtual precisa ser compatível com leitores de tela.', '["Assertiva que isenta empresas privadas da acessibilidade de seus sítios erra."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
