select u.id, u.content_sha256, 'As empresas prestadoras de serviços de telecomunicações deverão garantir pleno acesso à pessoa com deficiência, conforme regulamentação específica.', '["Telecomunicações com pleno acesso."]'::jsonb, '["Conforme regulamentação específica."]'::jsonb, 'A operadora oferece canais de atendimento acessíveis.', '["Assertiva que isenta as operadoras de telefonia da acessibilidade erra."]'::jsonb, '[]'::jsonb, '["Art. 66"]'::jsonb, 'under_review', 'claude'
