insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cabe ao poder público incentivar a oferta de aparelhos de telefonia fixa e móvel celular com acessibilidade que, entre outras tecnologias assistivas, possuam possibilidade de indicação e ampliação sonoras de todas as operações e funções disponíveis.', '["Incentivo a aparelhos acessíveis."]'::jsonb, '["Incentivo (não obrigação direta ao fabricante)."]'::jsonb, 'O celular lê em voz alta as funções do menu.', '["Assertiva que proíbe o incentivo a aparelhos acessíveis erra."]'::jsonb, '[]'::jsonb, '["Art. 65"]'::jsonb, 'under_review', 'claude'
