insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os serviços de radiodifusão de sons e imagens devem permitir o uso, entre outros, da subtitulação por meio de legenda oculta, de janela com intérprete da Libras e da audiodescrição.', '["Legenda oculta.","Janela com intérprete de Libras.","Audiodescrição."]'::jsonb, '["Três recursos principais."]'::jsonb, 'A emissora transmite o programa com legenda oculta e janela de Libras.', '["Assertiva que dispensa a audiodescrição na radiodifusão erra."]'::jsonb, '[{"termo":"Audiodescrição","significado":"Narração de elementos visuais para pessoas cegas."}]'::jsonb, '["Art. 70"]'::jsonb, 'under_review', 'claude'
