insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve adotar mecanismos de incentivo à produção, edição, difusão, distribuição e comercialização de livros em formatos acessíveis, inclusive em publicações da administração pública ou financiadas com recursos públicos. Nos editais de compras de livros, o poder público deverá adotar cláusulas de impedimento à participação de editoras que não ofertem sua produção também em formatos acessíveis. Consideram-se formatos acessíveis os arquivos digitais reconhecidos por leitores de tela ou outras tecnologias assistivas, permitindo leitura com voz sintetizada, ampliação de caracteres, contrastes e impressão em Braille. Deve-se estimular a adaptação de artigos científicos em formato acessível, inclusive em Libras.', '["Incentivo a livros em formatos acessíveis.","Editais impedem editoras que não ofertem formato acessível.","Conceito de formato acessível.","Artigos científicos em formato acessível e Libras."]'::jsonb, '["Editoras sem formato acessível são impedidas de participar de compras públicas de livros."]'::jsonb, 'A editora só vende livros ao governo se oferecer também versões acessíveis.', '["Assertiva que permite a compra pública de livros apenas em formato impresso comum erra."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-68' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '655753e325225ae43f336b88e312291e2ec9b2ed1f2d650018cc88299c081218'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público deve assegurar a disponibilidade de informações corretas e claras sobre os diferentes produtos e serviços, por quaisquer meios, inclusive virtual, com a especificação de quantidade, qualidade, características, composição e preço, bem como sobre os eventuais riscos à saúde e à segurança do consumidor com deficiência. Os canais de comercialização virtual e os anúncios devem disponibilizar os recursos de acessibilidade do art. 67, a expensas do fornecedor. Os fornecedores devem disponibilizar, mediante solicitação, bulas, prospectos e materiais de divulgação em formato acessível.', '["Informações claras e acessíveis sobre produtos e serviços.","Recursos de acessibilidade nos anúncios, a expensas do fornecedor.","Bulas e materiais em formato acessível, mediante solicitação."]'::jsonb, '["Custeio dos recursos de acessibilidade pelo FORNECEDOR."]'::jsonb, 'O laboratório fornece a bula em formato acessível, quando solicitado.', '["Assertiva que transfere ao consumidor o custo dos recursos de acessibilidade na publicidade erra."]'::jsonb, '[]'::jsonb, '["Art. 67"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-69' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c16888743293ad9876d0130228210d6160441373c7142afccffb9e80d4fa77b2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As instituições promotoras de congressos, seminários, oficinas e demais eventos de natureza científico-cultural devem oferecer à pessoa com deficiência, no mínimo, os recursos de tecnologia assistiva previstos no art. 67.', '["Eventos científicos e culturais: pelo menos os recursos do art. 67."]'::jsonb, '["Mínimo: legenda, Libras e audiodescrição."]'::jsonb, 'O congresso oferece intérprete de Libras e legenda.', '["Assertiva que dispensa recursos de acessibilidade em eventos privados erra."]'::jsonb, '[]'::jsonb, '["Art. 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-70' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ed137311a920813a7846ad9d280c23e615199c281dd3521874e3b6074fb6177c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
