insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os congressos, seminários, oficinas e demais eventos de natureza científico-cultural promovidos ou financiados pelo poder público devem garantir as condições de acessibilidade e os recursos de tecnologia assistiva.', '["Eventos públicos ou financiados pelo poder público garantem acessibilidade."]'::jsonb, '["Alcança os eventos FINANCIADOS pelo poder público."]'::jsonb, 'O seminário financiado pelo governo oferece todos os recursos de acessibilidade.', '["Assertiva que restringe a obrigação a eventos realizados em prédios públicos erra."]'::jsonb, '[]'::jsonb, '["Art. 70"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-71' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b9bb6906541e4569aaf2f79278fc0386bfc9067bb53ab7686c27b567eb206642'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
