insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os programas, linhas de pesquisa e projetos desenvolvidos com apoio de agências de financiamento e de órgãos da administração pública que atuem no auxílio à pesquisa devem contemplar temas voltados à tecnologia assistiva.', '["Pesquisa financiada deve contemplar tecnologia assistiva."]'::jsonb, '["Fomento à tecnologia assistiva."]'::jsonb, 'A agência de fomento inclui um edital para tecnologia assistiva.', '["Assertiva que exclui a tecnologia assistiva das linhas de pesquisa financiadas erra."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-72' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1c3b45312c7a1c1f55b43592c48b4347cea2bd8aacf64dd0f516270f884ae611'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
