insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá ao poder público, diretamente ou em parceria com organizações da sociedade civil, promover a capacitação de tradutores e intérpretes da Libras, de guias intérpretes e de profissionais habilitados em Braille, audiodescrição, estenotipia e legendagem.', '["Capacitação de intérpretes de Libras, guias intérpretes e profissionais de Braille, audiodescrição, estenotipia e legendagem."]'::jsonb, '["Pode ser em parceria com a sociedade civil."]'::jsonb, 'O governo financia cursos para intérpretes de Libras.', '["Assertiva que atribui só à iniciativa privada a capacitação desses profissionais erra."]'::jsonb, '[]'::jsonb, '["Art. 67"]'::jsonb, 'under_review', 'claude'
