insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As campanhas sociais, preventivas e educativas devem ser acessíveis à pessoa com deficiência.', '["Campanhas acessíveis."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'A campanha de vacinação tem versão em Libras e audiodescrição.', '["Assertiva que dispensa a acessibilidade das campanhas educativas erra."]'::jsonb, '[]'::jsonb, '["Art. 67"]'::jsonb, 'under_review', 'claude'
