insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedado exigir o comparecimento de pessoa com deficiência perante os órgãos públicos quando seu deslocamento, em razão de sua limitação funcional e de condições de acessibilidade, imponha-lhe ônus desproporcional e indevido. Quando for de interesse do poder público, o agente promoverá o contato em sua residência; quando for de interesse da pessoa, ela apresentará solicitação de atendimento domiciliar ou fará representar-se por procurador. É assegurado atendimento domiciliar pela perícia médica e social do INSS, pelo serviço de saúde e pelas entidades do Suas, quando o deslocamento imponha ônus desproporcional.', '["Vedada a exigência de comparecimento quando o deslocamento é um ônus desproporcional.","Atendimento domiciliar ou por procurador.","Perícia domiciliar do INSS."]'::jsonb, '["Perícia do INSS pode ser DOMICILIAR."]'::jsonb, 'O perito do INSS vai à casa da pessoa que não consegue se deslocar.', '["Assertiva que obriga o comparecimento presencial em qualquer caso erra: pode haver atendimento domiciliar."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-95' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b535ac5d5651c19028d5e58482fac612654f72b0a8fb1dce69453ea69d87be5c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O §6º-A do art. 135 do Código Eleitoral passa a prever que os Tribunais Regionais Eleitorais deverão, a cada eleição, expedir instruções aos Juízes Eleitorais para orientá-los na escolha dos locais de votação, de maneira a garantir acessibilidade ao eleitor com deficiência ou mobilidade reduzida, inclusive em seu entorno e nos sistemas de transporte que lhe dão acesso.', '["Instruções dos TREs para escolha de locais de votação acessíveis."]'::jsonb, '["ATUALIZAÇÃO: altera o Código Eleitoral."]'::jsonb, 'O TRE orienta os juízes a escolher locais de votação acessíveis.', '["Assertiva que dispensa a acessibilidade do entorno do local de votação erra."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-96' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f2ca02c9d229560828b9b212b72c6184764ff38a33017172d1fe0549a580bb80'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A CLT passa a vigorar com alterações: para fins do contrato de aprendizagem, a comprovação de escolaridade do aprendiz com deficiência considera, sobretudo, as habilidades e competências relacionadas com a profissionalização; para o aprendiz com deficiência com 18 anos ou mais, a validade do contrato pressupõe anotação na CTPS e matrícula e frequência em programa de aprendizagem; e o desempenho insuficiente ou a inadaptação do aprendiz não justificam a extinção do contrato quando o aprendiz com deficiência estiver desprovido de recursos de acessibilidade, tecnologias assistivas e apoio necessário.', '["Escolaridade do aprendiz com deficiência avaliada pelas habilidades.","Contrato de aprendizagem com CTPS e programa.","Sem extinção por inadaptação se faltar acessibilidade."]'::jsonb, '["ATUALIZAÇÃO: altera os arts. 428 e 433 da CLT."]'::jsonb, 'O aprendiz com deficiência não pode ser desligado por inadaptação se faltaram recursos de acessibilidade.', '["Assertiva que permite extinguir o contrato por inadaptação mesmo sem recursos de acessibilidade erra."]'::jsonb, '[]'::jsonb, '["CLT"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-97' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'be6b0dc6195e450dffc54a235eafaf44f35ffd4da02a4c641a17fddcf4824914'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei nº 7.853, de 24 de outubro de 1989, passa a vigorar com alterações: as medidas judiciais de proteção de interesses coletivos, difusos, individuais homogêneos e indisponíveis da pessoa com deficiência podem ser propostas pelo Ministério Público, Defensoria Pública, União, Estados, Municípios, Distrito Federal, por associação constituída há mais de 1 ano, por autarquia, empresa pública, fundação ou sociedade de economia mista. Constitui crime punível com reclusão de 2 a 5 anos e multa recusar, cobrar valores adicionais, suspender, procrastinar, cancelar ou fazer cessar inscrição de aluno em razão da deficiência; obstar inscrição em concurso público ou acesso a cargo ou emprego público; negar ou obstar emprego, trabalho ou promoção; recusar ou dificultar internação ou assistência médico-hospitalar, entre outras condutas.', '["Legitimados para ações coletivas, inclusive associação com mais de 1 ano.","Crimes da Lei nº 7.853: recusa de matrícula, obstar concurso ou emprego, negar assistência.","Reclusão de 2 a 5 anos e multa."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 7.853, de 1989.","Reclusão de 2 a 5 anos."]'::jsonb, 'A escola que se recusa a matricular aluno por causa da deficiência pratica crime.', '["Assertiva que prevê detenção para a recusa de matrícula por deficiência erra: é reclusão de 2 a 5 anos."]'::jsonb, '[]'::jsonb, '["Art. 88"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-98' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '43946c8a3e88311d9a0923e354f2ec65aa208840880dd8cbb65bf6cbee78f771'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 20 da Lei nº 8.036, de 11 de maio de 1990 (FGTS), passa a vigorar com o inciso XVIII, permitindo o saque do FGTS quando o trabalhador com deficiência, por prescrição, necessite adquirir órtese ou prótese para promoção de acessibilidade e de inclusão social.', '["Saque do FGTS para compra de órtese ou prótese, mediante prescrição."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei do FGTS."]'::jsonb, 'O trabalhador saca o FGTS para comprar uma prótese prescrita.', '["Assertiva que veda o saque do FGTS para órteses e próteses erra."]'::jsonb, '[]'::jsonb, '["Lei do FGTS"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-99' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8cc7d372fe37de7306077c95c8d0bde9928d0f6c4f43fb3d2937fcabd32ef1b4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código de Defesa do Consumidor passa a vigorar com alterações: a informação adequada e clara sobre produtos e serviços deve ser acessível à pessoa com deficiência, conforme regulamento; e todas as informações sobre cadastros e dados de consumidores devem ser disponibilizadas em formatos acessíveis, inclusive para a pessoa com deficiência, mediante solicitação do consumidor.', '["Informação ao consumidor em formato acessível.","Cadastros de consumidores em formato acessível."]'::jsonb, '["ATUALIZAÇÃO: altera o Código de Defesa do Consumidor (arts. 6º e 43)."]'::jsonb, 'O consumidor com deficiência visual pede em formato acessível os dados de seu cadastro.', '["Assertiva que isenta o fornecedor de prestar informações acessíveis ao consumidor com deficiência erra."]'::jsonb, '[]'::jsonb, '["Código de Defesa do Consumidor"]'::jsonb, 'under_review', 'claude'
