insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Lei nº 8.213, de 24 de julho de 1991, passa a vigorar com alterações: inclui como dependentes o filho ou irmão não emancipado menor de 21 anos, inválido ou que tenha deficiência intelectual, mental ou grave; mantém a cota de pensão para o filho ou irmão com deficiência além dos 21 anos; e dispõe sobre a reserva de cargos para pessoas com deficiência e beneficiários reabilitados, determinando que a dispensa de pessoa com deficiência ao final de contrato por prazo determinado de mais de 90 dias e a dispensa imotivada em contrato por prazo indeterminado só ocorram após a contratação de outro trabalhador com deficiência ou reabilitado.', '["Dependentes com deficiência intelectual, mental ou grave.","Pensão mantida para filho ou irmão com deficiência.","Dispensa condicionada à contratação de substituto com deficiência."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei de Benefícios da Previdência Social (arts. 16, 77 e 93).","Dispensa só após a contratação de outro trabalhador com deficiência ou reabilitado."]'::jsonb, 'A empresa só pode dispensar o empregado com deficiência após contratar outro.', '["Assertiva que permite a dispensa imediata do empregado cotista sem substituição erra."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-101' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '422f76cb081f42178affa65215a33e479f5fab4c9962a5db5cfca8f541cc8e5d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
