insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 2º da Lei nº 8.313, de 23 de dezembro de 1991 (Lei de Incentivo à Cultura), passa a vigorar acrescido do §3º: os incentivos somente serão concedidos a projetos culturais que forem disponibilizados, sempre que tecnicamente possível, também em formato acessível à pessoa com deficiência, conforme regulamento.', '["Incentivos culturais condicionados à oferta em formato acessível, quando possível."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei de Incentivo à Cultura."]'::jsonb, 'O projeto cultural incentivado também é oferecido em formato acessível.', '["Assertiva que dispensa o formato acessível nos projetos incentivados erra: é exigido quando tecnicamente possível."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
