insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Estatuto da Cidade (Lei nº 10.257, de 10 de julho de 2001) passa a vigorar com alterações: a União deve promover programas de construção de moradias, saneamento, calçadas, passeios públicos e mobiliário urbano; as diretrizes de desenvolvimento urbano incluem regras de acessibilidade aos locais de uso público; e as cidades obrigadas a ter plano diretor devem elaborar plano de rotas acessíveis, compatível com o plano diretor, para os passeios públicos a serem implantados ou reformados.', '["Acessibilidade nas diretrizes de desenvolvimento urbano.","Plano de rotas acessíveis nas cidades com plano diretor."]'::jsonb, '["ATUALIZAÇÃO: altera o Estatuto da Cidade (arts. 3º e 41)."]'::jsonb, 'A cidade elabora plano de rotas acessíveis para as calçadas.', '["Assertiva que dispensa o plano de rotas acessíveis nas cidades com plano diretor erra."]'::jsonb, '[]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-113' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '85d672e93f442541f06591a17f94126cb74fb346ff30107d2bb3d02b38e3a3cd'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
