insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Título IV do Livro IV da Parte Especial do Código Civil passa a ter a redação: Da Tutela, da Curatela e da Tomada de Decisão Apoiada.', '["Novo título: tutela, curatela e tomada de decisão apoiada."]'::jsonb, '["ATUALIZAÇÃO: altera a nomenclatura do Título IV do Código Civil."]'::jsonb, 'O Código Civil agora trata da tomada de decisão apoiada no mesmo título da curatela.', '["Assertiva que não prevê a tomada de decisão apoiada no Código Civil erra."]'::jsonb, '[]'::jsonb, '["Art. 116"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-115' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'aa1deeba27c7cee06b6b682d5e9c119f146384ecc38f507098074afbe05b1f6e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
