insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código Civil passa a ter o Capítulo III, da Tomada de Decisão Apoiada. Ela é o processo pelo qual a pessoa com deficiência elege pelo menos 2 pessoas idôneas, com as quais mantenha vínculos e que gozem de sua confiança, para prestar-lhe apoio na tomada de decisão sobre atos da vida civil, fornecendo-lhes os elementos e informações necessários. Para o pedido, a pessoa e os apoiadores apresentam termo com os limites do apoio e os compromissos, inclusive o prazo de vigência. O pedido é requerido pela pessoa apoiada, com indicação dos apoiadores. Antes de decidir, o juiz, assistido por equipe multidisciplinar e ouvido o Ministério Público, ouve pessoalmente o requerente e os apoiadores.', '["Tomada de decisão apoiada.","Pelo menos 2 apoiadores idôneos.","Termo com limites do apoio e prazo de vigência.","Pedido pela própria pessoa apoiada.","Juiz ouve pessoalmente os envolvidos, com equipe multidisciplinar e MP."]'::jsonb, '["Mínimo de 2 apoiadores.","O pedido é da PRÓPRIA pessoa apoiada, e ela mantém sua capacidade."]'::jsonb, 'A pessoa escolhe dois amigos de confiança para apoiá-la nos contratos que fizer.', '["Assertiva que permite a tomada de decisão apoiada com um único apoiador erra: são pelo menos 2."]'::jsonb, '[{"termo":"Tomada de decisão apoiada","significado":"Apoio escolhido pela pessoa com deficiência para decidir, sem perder a capacidade."}]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-116' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c0fa85cff8e39b3043e61ca042a1bf0d5b29ac93ff2f179b8832956430d61466'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 1º da Lei nº 11.126, de 27 de junho de 2005, passa a assegurar à pessoa com deficiência visual acompanhada de cão-guia o direito de ingressar e permanecer com o animal em todos os meios de transporte e em estabelecimentos abertos ao público, de uso público e privados de uso coletivo, e a aplicar-se a todas as modalidades e jurisdições do transporte coletivo de passageiros, inclusive em esfera internacional com origem no território brasileiro.', '["Direito ao cão-guia em transportes e estabelecimentos.","Alcança o transporte internacional com origem no Brasil."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei do Cão-Guia."]'::jsonb, 'A pessoa cega entra no restaurante com o cão-guia.', '["Assertiva que permite barrar o cão-guia em estabelecimentos privados de uso coletivo erra."]'::jsonb, '[]'::jsonb, '["Lei do Cão-Guia"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-117' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c29704efe7977301e5a64801d06b00a14dfc9eac7eedf452f1d17c8507d27bc2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O inciso IV do art. 46 da Lei nº 11.904, de 14 de janeiro de 2009 (Estatuto de Museus), passa a vigorar acrescido da alínea k, prevendo a acessibilidade a todas as pessoas entre os itens do plano museológico.', '["Acessibilidade a todas as pessoas no plano museológico."]'::jsonb, '["ATUALIZAÇÃO: altera o Estatuto de Museus."]'::jsonb, 'O museu inclui a acessibilidade no seu plano museológico.', '["Assertiva que dispensa a acessibilidade no plano museológico erra."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-118' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '80475d6f6d3cafaae04701c50bf1a18ad3bd672b9e83ad108222d7bc1b7bdd15'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
