insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cabe aos órgãos competentes, em cada esfera de governo, elaborar relatórios circunstanciados sobre o cumprimento dos prazos estabelecidos pelas Leis nº 10.048, de 8 de novembro de 2000, e nº 10.098, de 19 de dezembro de 2000, e encaminhá-los ao Ministério Público e aos órgãos de regulação. Os relatórios devem ser apresentados no prazo de 1 ano a contar da entrada em vigor da Lei.', '["Relatórios sobre o cumprimento dos prazos de acessibilidade.","Envio ao Ministério Público e órgãos de regulação.","Prazo de 1 ano."]'::jsonb, '["Relatórios em 1 ano."]'::jsonb, 'Cada esfera de governo apresenta relatório sobre a acessibilidade ao Ministério Público.', '["Assertiva que fixa em 5 anos o prazo dos relatórios erra: é 1 ano."]'::jsonb, '[]'::jsonb, '["Art. 127"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-120' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0fe86ee975950ecf608028e51a7940aa5a4e69d3f720c41efdc5584153bf2335'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os direitos, prazos e obrigações previstos na Lei não excluem os já estabelecidos em outras legislações, inclusive em pactos, tratados, convenções e declarações internacionais aprovados e promulgados pelo Congresso Nacional, e devem ser aplicados em conformidade com as demais normas internas e acordos internacionais vinculantes. Prevalecerá a norma mais benéfica à pessoa com deficiência.', '["Soma-se a outras legislações e tratados.","Prevalece a norma mais benéfica."]'::jsonb, '["Princípio da norma MAIS BENÉFICA."]'::jsonb, 'Entre a lei interna e o tratado, aplica-se o que for melhor à pessoa com deficiência.', '["Assertiva que prefere sempre a lei interna ao tratado erra: prevalece a norma mais benéfica."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-121' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0fe82a409912509d8facf3d7cfdc35af78aa39307df1ad5eb29b83896b04deb1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regulamento disporá sobre a adequação do disposto na Lei ao tratamento diferenciado, simplificado e favorecido a ser dispensado às microempresas e às empresas de pequeno porte, previsto no §3º do art. 1º da Lei Complementar nº 123, de 14 de dezembro de 2006.', '["Adequação às microempresas e empresas de pequeno porte por regulamento."]'::jsonb, '["Tratamento favorecido às ME e EPP."]'::jsonb, 'Uma microempresa pode ter prazos adaptados para cumprir as regras.', '["Assertiva que isenta as microempresas de qualquer obrigação de acessibilidade erra: o regulamento só adequa."]'::jsonb, '[]'::jsonb, '["Art. 125"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-122' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ef77062c78107a631684fbf9c500c5e4a8818dfba533871507e0ce9512598d39'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revogam-se dispositivos de outras leis incompatíveis com o novo regime, entre eles o inciso II do §2º do art. 1º da Lei nº 9.008, de 21 de março de 1995; os incisos I, II e III do art. 3º do Código Civil; os incisos II e III do art. 228; o inciso I do art. 1.548; o inciso IV do art. 1.557; os incisos II e IV do art. 1.767; e os arts. 1.776 e 1.780 do Código Civil.', '["Revoga incisos do Código Civil sobre incapacidade absoluta e outros.","Revoga o inciso II do §2º do art. 1º da Lei nº 9.008."]'::jsonb, '["Revogação de regras que tratavam a deficiência como incapacidade."]'::jsonb, 'Foi revogada a regra que tornava absolutamente incapaz quem tinha deficiência mental.', '["Assertiva que mantém os incisos do art. 3º do Código Civil sobre incapacidade absoluta erra: foram revogados."]'::jsonb, '[]'::jsonb, '["Art. 114"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-123' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b9f3fa1e24b31caa25a430180ac7cd1f165b21c72508598d3e97c12c7533beb7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O §1º do art. 2º da Lei deverá entrar em vigor em até 2 anos, contados da entrada em vigor da Lei.', '["Avaliação biopsicossocial deveria entrar em vigor em até 2 anos."]'::jsonb, '["ATUALIZAÇÃO: o prazo de 2 anos foi objeto de prorrogações e regulamentação posterior; confira a regulamentação da avaliação biopsicossocial."]'::jsonb, 'A avaliação biopsicossocial tinha prazo de dois anos para ser implementada.', '["Assertiva que fixa em 10 anos o prazo do §1º do art. 2º erra: eram 2 anos."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-124' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7fffa51252c3fea32c6943cfedb240e1733f7a51433bdd1a5d3183be4e128a13'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Devem ser observados os prazos, a partir da entrada em vigor da Lei, para o cumprimento de dispositivos: incisos I e II do §2º do art. 28, 48 meses; §6º do art. 44, 84 meses; art. 45, 24 meses; e art. 49, 48 meses.', '["Art. 28, §2º, I e II: 48 meses.","Art. 44, §6º: 84 meses.","Art. 45: 24 meses.","Art. 49: 48 meses."]'::jsonb, '["Prazos de transição de 24, 48 e 84 meses."]'::jsonb, 'Os hotéis tinham 24 meses para cumprir as regras do art. 45.', '["Assertiva que fixa em 12 meses o prazo para os hotéis erra: eram 24 meses."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-125' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6e14ad2740bde42f7bc7a545e92a02f224ddc19f8556f7b0c0b904dd1fc9fb20'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prorroga-se até 31 de dezembro de 2021 a vigência da Lei nº 8.989, de 24 de fevereiro de 1995, que trata da isenção do IPI na aquisição de automóveis por pessoas com deficiência.', '["Prorroga a isenção do IPI até 31 de dezembro de 2021."]'::jsonb, '["ATUALIZAÇÃO: a isenção foi prorrogada por leis posteriores; confira a vigência atual."]'::jsonb, 'A prorrogação garantiu a isenção do IPI na compra do veículo adaptado até 2021.', '["Assertiva que torna definitiva essa prorrogação erra: ela era até 31 de dezembro de 2021."]'::jsonb, '[]'::jsonb, '["Art. 125"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'pcd' and u.unit_key = 'art-126' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '414a50d62757f0569ffa1d651d0fc71b788816a51f67ebae57b8c31843ea2cad'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei entra em vigor após decorridos 180 dias de sua publicação oficial.', '["Vacatio legis de 180 dias."]'::jsonb, '["Vacatio legis de 180 dias."]'::jsonb, 'A Lei só passou a valer 180 dias depois de publicada.', '["Assertiva que prevê vigência imediata erra: são 180 dias."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
